Local Ltac dispatch_arm ARM CTX PURE HBS Hc :=
  step; step; step; step; step; step; step;
  first [ rewrite <- ASHADOW_BASE_val; fold (wz ASHADOW_BASE);
          eapply (ARM BCMP); [exact CTX | exact PURE | exact HBS | cbn; lia | exact Hc]
        | eapply verb_fail; [exact CTX | exact PURE | rewrite HBS, zbytes_cons, Hc; apply verb_of_other; cbn; lia] ].
